// O que interessa da mensagem que a Evolution mandou.
//
// Sai fora o que não é conversa de cliente: mensagem que a própria barbearia
// enviou, grupo, e evento que não é de mensagem (a Evolution manda dezenas de
// tipos no mesmo webhook).
const body = $json.body || {};
const dados = body.data || {};

if (body.event && body.event !== 'messages.upsert') return [];
if (dados?.key?.fromMe) return [];

const jid = dados?.key?.remoteJid || dados?.key?.remoteJidAlt || '';
if (String(jid).includes('@g.us')) return []; // grupo não é atendimento

const telefone = String(jid).split('@')[0].replace(/\D/g, '');
if (!telefone) return [];

const m = dados?.message || {};
const texto = String(
  m.conversation ||
    m.extendedTextMessage?.text ||
    m.imageMessage?.caption ||
    m.videoMessage?.caption ||
    m.buttonsResponseMessage?.selectedDisplayText ||
    m.listResponseMessage?.title ||
    '',
).trim();

// Áudio, figurinha e localização: o agente não lê, então é melhor dizer isso
// do que ficar mudo.
const semTexto = !texto && (m.audioMessage || m.stickerMessage || m.documentMessage || m.locationMessage);

return [
  {
    json: {
      telefone,
      // A instância é quem diz de qual barbearia é a conversa. Vem da própria
      // Evolution — ninguém digita, e barbearia nova não pede configuração.
      instance: body.instance || dados?.instance || '',
      nome: String(dados?.pushName || '').trim(),
      mensagem: texto,
      semTexto: !!semTexto,
    },
  },
];

// A mensagem que vai sair, e a garantia de que ALGUMA coisa sai.
//
// Cliente que escreve e não recebe nada acha que a barbearia sumiu. Se o
// agente falhou, ele responde a desculpa — e a execução fica vermelha na
// lista, para alguém olhar.
const config = $('Onde ficam as coisas').item.json;
const doAgente = String($json.output ?? $json.text ?? '').trim();

const desculpa =
  'Opa! Tive um problema aqui no sistema agora. Já avisei o pessoal da barbearia — me manda de novo em alguns minutos, por favor.';

const numero = config.telefone.startsWith('55') ? config.telefone : `55${config.telefone}`;

return [
  {
    json: {
      evolutionUrl: config.evolutionUrl,
      instance: config.instance,
      numero,
      texto: doAgente || desculpa,
      deuCerto: !!doAgente,
    },
  },
];

// Áudio, figurinha, documento: o atendente não lê. Dizer isso é melhor do
// que ficar mudo e deixar a pessoa esperando.
const config = $('Onde ficam as coisas').item.json;
const numero = config.telefone.startsWith('55') ? config.telefone : `55${config.telefone}`;

return [
  {
    json: {
      evolutionUrl: config.evolutionUrl,
      instance: config.instance,
      numero,
      texto: config.semTexto
        ? 'Consigo te atender por texto, por aqui mesmo. Me escreve o que você precisa?'
        : 'Oi! Me diz como posso te ajudar — marcar, remarcar ou cancelar um horário?',
      deuCerto: true,
    },
  },
];
